    "G03G": {
      "code": "G03G",
      "level": 0,
      "parent": null,
      "ja": "",
      "en": "",
      "count": 0,
      "ipcCode": "",
      "fTerm": "ELECTROGRAPHY; ELECTROPHOTOGRAPHY; MAGNETOGRAPHY<br><br><b><u>Note(s)</u></b><br><br><ul type=\"\"1\"\"><li>This subclass <u>covers</u>:<b>[5]</b><ul type=\"\"disc\"\"><li>the production of permanent directly-visible pictures in conformity with an original picture or document, using an intermediate imagewise distribution of an electric or magnetic quantity, such as a charge pattern, an electric conductivity pattern, or a magnetic pattern;</li><li>the production of permanent directly-visible pictures using an intermediate imagewise distribution of an electric or magnetic quantity, when the origin and the way of generating said intermediate distribution are not relevant.</li></ul></li><li>This subclass <u>does not cover</u>:<ul type=\"\"disc\"\"><li>use of electric signals for the transmission of the picture information from the original to the reproduction, i.e. pictorial communication, which is covered by subclass <b>H04N</b>;</li><li>production of pictures by heat patterns exclusively, not using an electrostatic or magnetic pattern, which is covered by group <b>B41M 5/00</b>;</li><li>production of prints by transferring ink from a printing form to a printing surface, without physical contact and using the force of an electrostatic field, which is covered by subclass <b>B41M</b>;</li><li>selective printing mechanisms characterised by the selective supply of electric current, or the selective application of magnetism or radiation, to a printing material or impression-transfer material, which are covered by groups <b>B41J 2/385</b>, <b>B41J 2/435</b>.</li></ul></li></ul><br><br><b><u>Subclass indexes</u></b><br><table width=\"100%\"><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">ORIGINAL RECORDING, MEMBERS AND MATERIALS</td><td><b>5/00</b>, <b>7/00</b>, <b>9/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">ELECTROGRAPHIC PROCESSES AND APPARATUS</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Using a charge pattern</td><td><b>13/00</b>, <b>15/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Using patterns other than charge patterns</td><td><b>17/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Using deformation of thermoplastic layers</td><td><b>16/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">PROCESSES AND APPARATUS USING MAGNETIC PATTERNS</td><td><b>19/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">DETAILS NOT OTHERWISE PROVIDED FOR</td><td><b>8/00</b>, <b>11/00</b>, <b>21/00</b></td></p></tr></table>",
      "childFlag": 0,
      "sourceFile": "fi_G.txt",
      "kind": "fi"
    },
