      "ja": "帯電像以外の像を用いる電子写真方式，例．導電性像；泳動を含む方式，例．光電気泳動，光電子ソログラフィー；選択転写を含む方式，例．電子写真粘着方式；本来そのような単一方式を含む装置［５］",
      "en": "Electrographic processes using patterns other than charge patterns, e.g. an electric conductivity pattern; Processes involving a migration; e.g. photoelectrophoresis, photoelectrosolography; Processes involving a selective transfer, e.g. electrophoto-adhesive processes; Apparatus essentially involving a single such process [5]",
